            if (!userExist) {
                OSKLoggingService.default.logInfo(
                    'maintenance - - user does not exist in /users/ collection, its accesses will be removed from buildings/accesses',
                    {
                        userId: buildingAccessDoc.userId,
                        buildingId,
                        buildingAccessDoc,
                    }
                );

                // remove user access from building accesses
                return await OSKBuildingAccessesController.default.deletePerUser(buildingId, buildingAccessDoc.userId);
            }
        }

async (buildingAccessDoc) => {
            const userId = buildingAccessDoc.userId;
            let userAccesses: OSKUserAccessesDocument | undefined;
            try {
                userAccesses = await OSKUserAccessesController.default.getPerBuilding(userId, buildingId);
            } catch (error) {
                OSKLoggingService.default.logError(
                    `maintenance - - Error when trying to get access from user ${userId} in building ${buildingId}`,
                    {
                        buildingAccessDoc,
                        buildingId,
                    }
                );
                return;
            }

            if (!userAccesses) {
                OSKLoggingService.default.logInfo(
                    `maintenance - - user ${userId} does not have accesses for this building, its accesses will be removed from building ${buildingId}/accesses`,
                    {
                        userId: buildingAccessDoc.userId,
                        buildingId,
                        buildingAccessDoc,
                    }
                );
                // remove user access from building accesses
                return OSKBuildingAccessesController.default.deletePerUser(buildingId, buildingAccessDoc.userId);
            } else {
                OSKLoggingService.default.logInfo(
                    `maintenance - - user ${userId} accesses will update building ${buildingId} accesses`,
                    {
                        buildingId,
                        buildingAccessDoc,
                    }
                );
                // update building accesses with user accesses
                return OSKBuildingAccessesController.default.update(buildingId, userId, {
                    accesses: userAccesses.accesses,
                });
            }
        }

async (buildingAccessDoc) => {
            const userId = buildingAccessDoc.userId;

            // Get user accesses. This is still a single, awaited operation per loop.
            const userAccessesDoc: OSKDbUserAccessDocumentBadAccesses =
                await OSKUserAccessesController.default.getPerBuildingSafe(userId, buildingId);

            const userAccessesPromises = [];
            const buildingAccessesPromises = [];

            // Check and update user accesses
            if (userAccessDocWithAccesses(userAccessesDoc)) {
                userAccessesPromises.push(OSKDbAccessService.checkUserMainAccess(userAccessesDoc, userId, buildingId));
            } else {
                OSKLoggingService.default.logWarning(
                    `maintenance - - cannot update user ${userId} accesses, they are missing`
                );
            }

            // Check and update building accesses
            if (buildingAccessDocWithAccesses(buildingAccessDoc)) {
                buildingAccessesPromises.push(
                    OSKDbAccessService.checkBuildingMainAccess(buildingAccessDoc, userId, buildingId)
                );
            } else {
                OSKLoggingService.default.logWarning(
                    `maintenance - - cannot update building ${buildingId} accesses, they are missing`
                );
            }

            // return a promise that waits for both user and building updates for a single user to complete
            return Promise.all([...userAccessesPromises, ...buildingAccessesPromises]);
        }

